
const fs=require('fs'),path=require('path');const SITE=path.resolve(__dirname,'..'),SOURCE=path.join(SITE,'site-templates');const read=p=>fs.readFileSync(path.join(SITE,p),'utf8'),write=(p,s)=>{fs.mkdirSync(path.dirname(path.join(SITE,p)),{recursive:true});fs.writeFileSync(path.join(SITE,p),s)};const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const L=(l,a,e)=>l==='ar'?a:e;const file=(n,l)=>n+(l==='en'?'-en':'')+'.html';const duration=n=>Math.floor(n/60)+':'+String(n%60).padStart(2,'0');const origin='https://azrar-systems.com';
