function head(l,title,description,name,extra=''){const url=origin+'/'+(name==='index'&&l==='ar'?'':file(name,l));return'<!doctype html><html lang="'+l+'" dir="'+(l==='ar'?'rtl':'ltr')+'" data-lang="'+l+'"><head><meta charset="utf-8">'+csp+'<meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="strict-origin-when-cross-origin"><meta name="theme-color" content="#10142b"><title>'+esc(title)+'</title><meta name="description" content="'+esc(description)+'"><meta name="robots" content="index,follow"><link rel="canonical" href="'+url+'"><link rel="alternate" hreflang="ar" href="'+origin+'/'+(name==='index'?'':file(name,'ar'))+'"><link rel="alternate" hreflang="en" href="'+origin+'/'+file(name,'en')+'"><link rel="alternate" hreflang="x-default" href="'+origin+'/'+(name==='index'?'':file(name,'ar'))+'"><meta property="og:type" content="website"><meta property="og:url" content="'+url+'"><meta property="og:title" content="'+esc(title)+'"><meta property="og:description" content="'+esc(description)+'"><meta property="og:image" content="'+origin+'/og-image.png"><meta property="og:locale" content="'+(l==='ar'?'ar_JO':'en_US')+'"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="favicon.ico"><link rel="stylesheet" href="site-shell.css"><link rel="stylesheet" href="site-pages.css">'+tracking+extra+'<script src="site.js" defer></script></head><body class="site-modern">';}
