function image(shot,alt,priority=false){return'<img src="assets/shots/'+shot+'-960.webp" srcset="assets/shots/'+shot+'-480.webp 480w, assets/shots/'+shot+'-960.webp 960w" sizes="(max-width:700px) 100vw, 55vw" width="1100" height="687" alt="'+esc(alt)+'" '+(priority?'fetchpriority="high"':'loading="lazy"')+' decoding="async">';}
function picture(shot,l,priority=false){return'<figure class="app-picture">'+image(shot,L(l,'واجهة أزرار الفعلية','Actual AZRAR desktop interface'),priority)+'<figcaption>'+L(l,'من واجهة أزرار للكمبيوتر · بيانات للعرض','AZRAR for Windows · sample display data · Arabic interface shown')+'</figcaption></figure>';}
function intro(l,k,title,desc){return'<section class="page-intro page-wrap"><p class="eyebrow">'+esc(k)+'</p><h1>'+esc(title)+'</h1><p class="lead">'+esc(desc)+'</p></section>';}
